import java.util.Scanner;
public class JAdjacentDuplicates {
	public static void main(String[] args) {
		//Khatwa 1: Iqra al-raqm al-awwal alladhi yadkhuluhu al-mustakhdim
		System.out.println("Adkhil al-a`dad mufasilah bimasafat aw satar jadeed (adkhil -1 lil-khuruj): ");
		Scanner scan = new Scanner(System.in); 
		double num = scan.nextDouble();
		//Khatwa 2: Iqra al-baqi min al-a`dad allatih yadkhuluha al-mustakhdim wa tafaqad al-takarrurat al-mutajawirah
		while (num != -1) {
			double previous = num;
			num = scan.nextDouble();
			if (num == previous) {
				System.out.println("Tadkhul mutakarrar lil-raqm: " + num); 
			}
		}
		scan.close();
	}
}
